// TH18 v1.00a Stage 1 wave 3 (MainSub02 / MainSub02b).
// Source: st01.ecl.txt:1512-1560; st01mbs.ecl.txt:619-716 (GirlB01),
//         359-438 (GirlA01/GirlA01_at), 786-798 (BlueA01n), 1246-1255 (RedA01n).
// Card frame = source t + 122 (120-frame opening buffer, then next-frame task starts).
const TIME_LIMIT: int = 1620;       // 120 buffer + 1500 local source estimate/tail
const OPENING_BUFFER: int = 120;
const SOURCE_ESTIMATE: int = 1500;  // last source bullet ~t1371 + tail

const TH18_BALL: int = 416;         // source st01mbs etSprite type 4
const TH18_RING_BALL2: int = 464;   // source st01mbs etSprite type 7

// GirlB01_at / GirlB01_at2 share et0: each async entry rewrites the config that
// all concurrently running etOn calls read. Only the ranked speed differs, so it
// is kept in the shared enemy fx slot and re-read at every volley.
async sub girl_gun(n: int, spd: fx) {
    set_self_fx(0, spd);
    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 4);
    sh_ring(0, 0);
    sh_aim(0, 1);
    sh_angle(0, 0deg, 0deg);
    for i in 0..n {
        sh_count(0, 1, 1);
        sh_speed(0, self_fx(0), 0fx);
        sh_fire(0);
        wait(20);
    }
}

// GirlA01_at: aimed 3-way fan, speed 1.5/1.5/3/4, one volley on E/N/H and
// three on L; on E/N the volley also has the source RAND%3 fire gate.
async sub a01_gun() {
    var rank: int = global(GVAR_RANK);
    wait(1 + rand(60));
    sh_reset(0);
    sh_sprite(0, TH18_BALL, 6);
    sh_ring(0, 0);
    sh_aim(0, 1);
    var cnt: int = 1;
    var spd: fx = 1.5fx;
    var n: int = 1;
    if rank >= 2 { spd = 3fx; }
    if rank == 3 { cnt = 3; spd = 4fx; n = 3; }
    sh_count(0, cnt, 1);
    sh_speed(0, spd, 0fx);
    sh_angle(0, 0deg, 30deg);
    for i in 0..n {
        var fire_ok: int = 1;
        if rank < 2 {
            if rand(3) != 0 { fire_ok = 0; }
        }
        if fire_ok == 1 { sh_fire(0); }
        wait(60);
    }
}

// GirlRedA01n / GirlBlueA01n -> GirlA01(0). Blue additionally starts
// GirlA01_at on N/H/L. Body/hurt boxes use the source 16/24 widths as radii.
async sub a01n(mirror: int, blue: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    if blue != 0 && global(GVAR_RANK) >= 1 { spawn a01_gun(); }
    move_vel(0, 90deg, 1fx, EASE_LINEAR);
    wait(30);
    var turn: angle = 35deg;
    if mirror != 0 { turn = 145deg; }
    move_angle(120, turn, EASE_QUAD_IN);
    move_speed(300, 2.5fx, EASE_QUAD_IN);
    loop { wait(60); }
}

// MainSub02b: three rounds, each B group 2 pairs then C group 2 pairs.
async sub red_blue_wave() {
    for round in 0..3 {
        for j in 0..2 {
            _ = spawn_enemy(-64fx, -32fx, 100, 0, 0, 0, a01n(0, 0)); // Red, plain
            _ = spawn_enemy(64fx, -32fx, 100, 0, 0, 0, a01n(1, 1));  // Blue, mirrored
            wait(20);
        }
        wait(100);
        for k in 0..2 {
            _ = spawn_enemy(64fx, -32fx, 100, 0, 0, 0, a01n(1, 0));  // Red, mirrored
            _ = spawn_enemy(-64fx, -32fx, 100, 0, 0, 0, a01n(0, 1)); // Blue, plain
            wait(20);
        }
        wait(100);
    }
}

// GirlB01: source moves (mode1 = quadratic in) with mirrored angles on M entries.
// at() entries at t=60,290,470 and at2() at t=530; loops run to t~541/541/541/811.
async sub girl_b01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);

    var rank: int = global(GVAR_RANK);
    var n1: int = 25;
    var s1: fx = 3.5fx;
    if rank == 0 { n1 = 1; s1 = 2.2fx; }
    if rank == 1 { n1 = 5; s1 = 2.2fx; }
    if rank == 2 { n1 = 15; s1 = 3fx; }
    var n2: int = 15;
    var s2: fx = 3.5fx;
    if rank == 0 { n2 = 2; s2 = 2.2fx; }
    if rank == 1 { n2 = 10; s2 = 2.2fx; }
    if rank == 2 { n2 = 15; s2 = 2.2fx; }

    var a_init: angle = 45deg;
    var a_stop: angle = 0deg;
    var a_diag: angle = -4096bam;   // source -0.3926991 rad
    var a_back: angle = 180deg;
    var a_last: angle = 4096bam;    // source 0.3926991 rad
    if mirror != 0 {
        a_init = 135deg;
        a_stop = 180deg;
        a_diag = 36864bam;          // 202.5deg
        a_back = 0deg;
        a_last = 28672bam;          // 157.5deg
    }
    move_vel(0, a_init, 4fx, EASE_LINEAR);
    move_vel(50, a_stop, 0fx, EASE_QUAD_IN);
    wait(60);
    spawn girl_gun(n1, s1);
    wait(110);
    move_vel(60, a_diag, 3fx, EASE_QUAD_IN);
    wait(60);
    move_vel(60, a_diag, 0fx, EASE_QUAD_IN);
    wait(60);
    spawn girl_gun(n1, s1);
    wait(60);
    move_vel(0, a_back, 0fx, EASE_LINEAR);
    move_vel(60, a_back, 3fx, EASE_QUAD_IN);
    wait(60);
    move_vel(60, a_back, 0fx, EASE_QUAD_IN);
    wait(60);
    spawn girl_gun(n1, s1);
    wait(60);
    move_vel(0, a_last, 0fx, EASE_LINEAR);
    move_vel(60, a_last, 2fx, EASE_QUAD_IN);
    spawn girl_gun(n2, s2);
    loop { wait(60); }
}

async sub wave() {
    wait(OPENING_BUFFER);
    spawn red_blue_wave();
    _ = spawn_enemy(-224fx, 96fx, 500, 0, 0, 0, girl_b01(0));
    wait(80);
    _ = spawn_enemy(224fx, 80fx, 500, 0, 0, 0, girl_b01(1));
    wait(80);
    _ = spawn_enemy(-224fx, 80fx, 500, 0, 0, 0, girl_b01(0));
    wait(80);
    _ = spawn_enemy(224fx, 96fx, 500, 0, 0, 0, girl_b01(1));
    wait(80);
    _ = spawn_enemy(-224fx, 80fx, 500, 0, 0, 0, girl_b01(0));
    wait(80);
    _ = spawn_enemy(224fx, 96fx, 500, 0, 0, 0, girl_b01(1));
    wait(80);
    _ = spawn_enemy(-224fx, 80fx, 500, 0, 0, 0, girl_b01(0));
    wait(80);
    _ = spawn_enemy(224fx, 96fx, 500, 0, 0, 0, girl_b01(1));
    loop { wait(1); }
}

async sub director() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, director);
    loop { wait(600); }
}
